Add-Type -AssemblyName System.Drawing
$root=Split-Path -Parent $PSScriptRoot;$scale=4;$cols=20;$rows=15;$cell=16;$font=[System.Drawing.Font]::new('Consolas',7,[System.Drawing.FontStyle]::Bold)
foreach($kind in @('Env','Castle')){$dir=Join-Path $root "src\KuroganesEcho.Core\Content\Tiled\Tilesets\$kind";$out=[System.Drawing.Bitmap]::new($cols*$cell*$scale,$rows*$cell*$scale,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[System.Drawing.Graphics]::FromImage($out);$g.Clear([System.Drawing.Color]::FromArgb(255,22,30,48));$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[System.Drawing.Drawing2D.PixelOffsetMode]::Half;for($r=0;$r -lt $rows;$r++){for($c=0;$c -lt $cols;$c++){$id=$r*$cols+$c;$file=Join-Path $dir ("tile_r{0:D2}_c{1:D2}_{2:D3}.png"-f$r,$c,$id);$bmp=[System.Drawing.Bitmap]::new($file);$px=$c*$cell*$scale;$py=$r*$cell*$scale;$g.DrawImage($bmp,$px,$py,$cell*$scale,$cell*$scale);$g.FillRectangle([System.Drawing.Brushes]::Black,$px,$py,30,12);$g.DrawString([string]($id+1),$font,[System.Drawing.Brushes]::White,$px,$py-1);$g.DrawRectangle([System.Drawing.Pens]::Yellow,$px,$py,$cell*$scale-1,$cell*$scale-1);$bmp.Dispose()}};$g.Dispose();$out.Save((Join-Path $PSScriptRoot ("$kind`_act03_labeled.png")),[System.Drawing.Imaging.ImageFormat]::Png);$out.Dispose()};$font.Dispose()
